import{_ as o,o as r,c as n,a3 as s}from"./chunks/framework.bijRUqYl.js";const a="/MoMAWork-/assets/wechat-qr._jEgA8FU.jpg",c=JSON.parse('{"title":"OPC 实战营","description":"","frontmatter":{},"headers":[],"relativePath":"community/index.md","filePath":"community/index.md"}'),e={name:"community/index.md"};function d(l,t,g,i,h,p){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="opc-实战营" tabindex="-1">OPC 实战营 <a class="header-anchor" href="#opc-实战营" aria-label="Permalink to &quot;OPC 实战营&quot;">​</a></h1><p><strong>一人公司的 AI 作业本</strong></p><blockquote><p>一个人，一支 AI 团队，一门跑得起来的生意。 <strong>不聊概念，只交作业。</strong></p></blockquote><div class="tip custom-block"><p class="custom-block-title">🚪 第一次来，随便挑一个开始</p><ul><li>📓 <strong><a href="/MoMAWork-/community/weekly/">这周的作业 →</a></strong> —— 你本来就要做的事，40 分钟内能交出东西</li><li>🏭 <strong><a href="/MoMAWork-/community/prompts/">70 条行业提示词 →</a></strong> —— 14 类行业与岗位，<strong>不用进群就能抄</strong></li><li>📚 <strong><a href="/MoMAWork-/bluebook/">白皮书 28 章 →</a></strong> —— 从「怎么把需求讲清楚」讲到「多 Agent 系统设计」</li><li>🤝 <strong><a href="#怎么加入">进群交作业 →</a></strong> —— 加我微信，<strong>你交的作业我一定回</strong></li></ul></div><p><strong>这个站现在有的东西</strong>：白皮书 <strong>28 章 / 5 篇</strong> · 案例库 <strong>6 个真实任务复盘</strong> · 行业提示词 <strong>14 类 70 条</strong> · 社区周刊 <strong>每周三期，已出 2 期</strong>。</p><hr><h2 id="📓-本周作业" tabindex="-1">📓 本周作业 <a class="header-anchor" href="#📓-本周作业" aria-label="Permalink to &quot;📓 本周作业&quot;">​</a></h2><blockquote><p><strong>📓 本期任务（第 2 期 · 周次 2026-w38）</strong> 把最常说的三句话写成提示词 👉 完整说明与提示词骨架在 <strong><a href="/MoMAWork-/community/weekly/2026-w38.html">第 2 期 · 2026-w38</a></strong></p></blockquote><p>任务<strong>每周一换</strong>，每一条都满足同一个标准：<strong>你本来就要做的事 + 40 分钟内能交付 + 交付物能贴出来</strong>。全部往期在 <strong><a href="/MoMAWork-/community/weekly/">社区周刊归档</a></strong>。</p><h2 id="这是个什么地方" tabindex="-1">这是个什么地方 <a class="header-anchor" href="#这是个什么地方" aria-label="Permalink to &quot;这是个什么地方&quot;">​</a></h2><p>一个人做事，最难的从来不是能力，是<strong>没人跟你一起</strong>：</p><ul><li>想到一个好点子，没人接你的话；</li><li>卡在一个环节上，没人拉你一把；</li><li>好不容易做完一件漂亮的事，<strong>没人知道你做了</strong>；</li><li>做砸了，更没人告诉你错在哪。</li></ul><p>你可以用 AI 补上&quot;人手&quot;——这是 MomaWork 存在的意义。但 AI <strong>补不上&quot;同行&quot;</strong>。OPC 社区就是来补这一块的。</p><p><strong>OPC = One Person Company</strong>，一人公司。但在我们这里，它<strong>不是</strong>一个工商注册形态，而是一种工作方式：</p><blockquote><p>一个人，把原本需要一支团队做的事，<strong>拆</strong>成一件件能交给 AI 干的事。</p></blockquote><p>会拆的人，一个人顶一支团队；不会拆的人，AI 再多，也只是个更聪明的搜索框。<strong>我们聚在一起，就是为了把&quot;拆&quot;这件事练熟。</strong></p><h3 id="和别的地方不一样在哪" tabindex="-1">和别的地方不一样在哪 <a class="header-anchor" href="#和别的地方不一样在哪" aria-label="Permalink to &quot;和别的地方不一样在哪&quot;">​</a></h3><p>讲一人公司的地方很多。绝大部分在讲<strong>为什么</strong>——趋势、自由、机会、睡后收入。我们不讲这个：不是因为它错，而是因为<strong>讲完改变不了任何事</strong>。</p><p>我们只讲<strong>怎么做</strong>，而且必须落到看得见的东西上：</p><table tabindex="0"><thead><tr><th></th><th>别人</th><th>我们</th></tr></thead><tbody><tr><td>内容</td><td>观点与故事</td><td><strong>作业</strong>：可复现的操作步骤</td></tr><tr><td>证明</td><td>收入截图</td><td><strong>交付物</strong>：文件、表格、Skill、上线的东西</td></tr><tr><td>归宿</td><td>收藏夹</td><td><strong>资产</strong>：往期作业、提示词、团队模板</td></tr></tbody></table><blockquote><p><strong>别人在讲&quot;我做到了&quot;，我们只讲&quot;你也来交一份&quot;。</strong></p></blockquote><hr><h2 id="社区怎么运转-六个栏目" tabindex="-1">社区怎么运转（六个栏目） <a class="header-anchor" href="#社区怎么运转-六个栏目" aria-label="Permalink to &quot;社区怎么运转（六个栏目）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>栏目</th><th>干什么</th></tr></thead><tbody><tr><td>🚩 <strong>新人报到</strong></td><td>进来先说说你是谁、在做什么、卡在哪</td></tr><tr><td>📓 <strong>作业本</strong></td><td><strong>社区的心脏</strong>：把你的实战过程交上来</td></tr><tr><td>🔧 <strong>Skill 集市</strong></td><td>把作业沉淀成可复用的 Skill，互相取用</td></tr><tr><td>👥 <strong>组队共创</strong></td><td>一个人啃不动的活，喊人一起</td></tr><tr><td>📅 <strong>活动日历</strong></td><td>每周任务、双周分享、月度上墙</td></tr><tr><td>🧰 <strong>资源库</strong></td><td>模板、提示词、清单，都是成员交上来的</td></tr></tbody></table><blockquote><p><strong>&quot;作业本&quot;排在第一位，不是装饰。</strong> 一个社区的气质，取决于它默认鼓励什么。我们默认鼓励&quot;交出来&quot;。</p></blockquote><h3 id="🧰-资源库-·-已经备好的第一件装备" tabindex="-1">🧰 资源库 · 已经备好的第一件装备 <a class="header-anchor" href="#🧰-资源库-·-已经备好的第一件装备" aria-label="Permalink to &quot;🧰 资源库 · 已经备好的第一件装备&quot;">​</a></h3><p><strong><a href="/MoMAWork-/community/prompts/">🏭 行业提示词模板库 →</a></strong>：14 类行业与岗位、每类 5 条高频场景模板（<strong>共 70 条</strong>）—— 通用办公 · 电商直播 · 门店餐饮 · 教育培训 · 房产中介 · 医疗药店 · 法律财税 · 销售跟进 · 人力招聘 · 自媒体 · 技术研发 · 外贸跨境 · 行政文秘 · 制造工厂。</p><p>每条都是「<strong>什么时候用 + 可复制的提示词 + 它给你什么</strong>」。没找到你这行？<a href="/MoMAWork-/community/prompts/">说一句「我是干 XX 的」</a>，下个月就给你做。</p><h2 id="📅-最近三期" tabindex="-1">📅 最近三期 <a class="header-anchor" href="#📅-最近三期" aria-label="Permalink to &quot;📅 最近三期&quot;">​</a></h2><blockquote><p><strong>每周三期：周一任务 / 周三装备 / 周日上墙与周报。</strong> 全部往期在 <strong><a href="/MoMAWork-/community/weekly/">社区周刊归档</a></strong>。</p></blockquote><table tabindex="0"><thead><tr><th>期次</th><th>周次</th><th>上线日期</th><th>周一 · 任务</th><th>周三 · 装备</th><th>周日 · 上墙与周报</th></tr></thead><tbody><tr><td><strong><a href="/MoMAWork-/community/weekly/2026-w38.html">第 2 期</a></strong></td><td>2026-w38</td><td>2026-09-14</td><td>把最常说的三句话写成提示词</td><td>装备 002 · 先给样例</td><td>上墙与周报 002 · 编辑部实测 002（本周墙空着）</td></tr><tr><td><strong><a href="/MoMAWork-/community/weekly/2026-w37.html">第 1 期</a></strong></td><td>2026-w37</td><td>2026-09-12</td><td>把每周重复做的事交给 AI</td><td>装备 001 · 三段式提示词骨架</td><td>上墙与周报 001 · 编辑部实测 001（本周墙空着）</td></tr><tr><td><a href="/MoMAWork-/community/weekly/">全部往期 →</a></td><td>—</td><td>—</td><td>归档页按周列出</td><td>装备库按周排期</td><td>每周日更新</td></tr></tbody></table><p><strong>没有成员交作业的周，也不会空着。</strong>「编辑部实测记录」顶上——我自己把这周的任务真跑一遍，过程、结果、踩的坑都写进当期周报（第 2 期就是<a href="/MoMAWork-/community/weekly/2026-w38.html">这样一篇</a>）。</p><h2 id="三条规矩" tabindex="-1">三条规矩 <a class="header-anchor" href="#三条规矩" aria-label="Permalink to &quot;三条规矩&quot;">​</a></h2><ol><li><strong>不晒收入，只晒交付物</strong>——证明你做成过一件事的方式，是把那份东西拿出来。</li><li><strong>不发外部资源包、不发硬广告</strong>——作业里可以带生意，广告里不许带作业。</li><li><strong>提问带上背景 + 已试过什么 + 卡在哪</strong>——这样别人才答得上。</li></ol><p><strong>一条铁律：你交的作业，24 小时内我一定会回你。</strong>（回你的人是编辑部，不是碰运气的群友。）回应慢一次，就少一个人交第二次。</p><p><strong>还有几条边界，说在前面：</strong></p><ul><li>❌ 不做 AI 工具资讯搬运——网上到处都是，我们不做第二份</li><li>❌ 不做&quot;月入 X 万&quot;的财富故事——一旦开始晒收入，来的人就不是来干活的</li><li>❌ 不做免费资源大礼包——靠白嫖聚起来的人不交作业，只会稀释气氛</li><li>❌ 不追人数——<strong>前 100 个人决定这个社区的气质</strong>；也不做没有交付物的活动</li></ul><p>如果你要的是&quot;看看别人怎么发财&quot;，这里不适合你，我不耽误你时间；<strong>如果你手上正好有一件想干成的事，留下。</strong></p><hr><h2 id="怎么加入" tabindex="-1">怎么加入 <a class="header-anchor" href="#怎么加入" aria-label="Permalink to &quot;怎么加入&quot;">​</a></h2><div style="text-align:center;margin:8px 0 4px;"><img src="'+a+'" alt="扫码加我微信，我拉你进群" width="200" height="200" style="border-radius:12px;box-shadow:0 4px 16px rgba(0,0,0,0.12);"><div style="font-size:14px;line-height:1.9;color:var(--vp-c-text-2);margin-top:12px;"><strong>扫码加我微信，我拉你进群</strong><br> 邮箱：<code>1972597219@qq.com</code></div></div><p><strong>第一步</strong>：扫上面的码加我微信，我拉你进群（也可以先发邮件到 <code>1972597219@qq.com</code>）。</p><p><strong>第二步</strong>：进群后做三件事——</p><ol><li>改备注：<code>昵称 · 在做什么</code></li><li>到 🚩 新人报到 发一条：<strong>我是谁 / 我在做什么 / 我现在卡在哪</strong></li><li>领走本周的一个任务（不用全做，挑一个）</li></ol><p><strong>第三步</strong>：做完交作业。哪怕只是一张截图、一段文字。<strong>先交一份不完美的，好过想一个月交一份完美的。</strong></p><h2 id="📮-作业交上来之后" tabindex="-1">📮 作业交上来之后 <a class="header-anchor" href="#📮-作业交上来之后" aria-label="Permalink to &quot;📮 作业交上来之后&quot;">​</a></h2><p>交作业不难，格式随意，但请带上这三样：</p><table tabindex="0"><thead><tr><th>要说清</th><th>例如（这是格式示范，不是谁的作业）</th></tr></thead><tbody><tr><td>你原来是怎么做的</td><td>&quot;以前写周报要 40 分钟：先翻聊天记录，再一条条拼&quot;</td></tr><tr><td>这次交给 AI 后是什么样</td><td>&quot;现在 10 分钟，我只改了 3 处&quot;</td></tr><tr><td>别人能不能照做</td><td>把你用的那句话、那张清单、那个提示词贴出来</td></tr></tbody></table><p><strong>我们的处理流程</strong>（每一步都有明确产出）：</p><ol><li><strong>你交</strong> → 24 小时内有人回应（这是铁律，不是礼貌）</li><li><strong>有人评</strong> → 只评做法，不评人；必须指出一个具体可改的点</li><li><strong>可复用就沉淀</strong> → 值得留下的作业，会被整理成 Skill 或模板，进 🧰 资源库</li><li><strong>每周日上墙</strong> → 上墙的是<strong>交付物</strong>，不是成绩</li></ol><blockquote><p><strong>被复用，是对一份作业最高的评价。</strong></p></blockquote><hr><p><strong>🪧 第一份作业的位置，留给你。</strong> 这一块将来放的是成员的真实作业与真实踩坑，<strong>现在还是空的</strong>——编出来的故事不配放在这儿，我不打算用&quot;某某靠这个方法赚到第一桶金&quot;撑门面。</p><p>想成为第一份？把作业发到群里，或直接私聊我（联系方式见上面「<a href="#怎么加入">怎么加入</a>」），说一句<strong>能不能公开 / 要不要署你的名</strong>；我整理后贴在这里，注明&quot;第 N 位交作业的人&quot;，<strong>不做任何美化</strong>，数字是几就写几。</p><hr><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>我们不做一个大而热闹的地方，我们做一个<strong>小而能生产</strong>的地方。</p><blockquote><p>一个人，一支 AI 团队，一门跑得起来的生意。 <strong>不聊概念，只交作业。</strong></p></blockquote><p><strong>合作 / 赞助 / 想一起做这事</strong>：<code>1972597219@qq.com</code>（或扫码加我微信）</p>',59)])])}const q=o(e,[["render",d]]);export{c as __pageData,q as default};
